package com.tencent.weknora.knowledge;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import com.tencent.weknora.model.client.*;
import com.tencent.weknora.task.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;

/** Native knowledge:auto_tag. Retries only add existing tags and never own a parse slot. */
public final class KnowledgeAutoTagHandler implements TaskHandler {
  public interface Models {ChatModel chat(long owner,String id);}
  private final KnowledgeAutoTagRepository repository;private final ObjectMapper json;private final Models models;private final KnowledgeProcessingSpanTracker tracker;private final KnowledgeAutoTagText text;private final KnowledgeFileUpload.Enqueuer tasks;
  public KnowledgeAutoTagHandler(KnowledgeAutoTagRepository repository,ObjectMapper json,Models models,KnowledgeProcessingSpanTracker tracker,KnowledgeFileUpload.Enqueuer tasks){this.repository=repository;this.json=json;this.models=models;this.tracker=tracker;this.tasks=tasks;text=new KnowledgeAutoTagText(json);}
  public String type(){return "knowledge:auto_tag";}
  public Duration timeout(){return Duration.ofMinutes(2);}
  public boolean enqueue(TaskRecord job,DocumentProcessingRepository.Snapshot snapshot,int textLikeCount){if(tasks==null||textLikeCount<=0||!snapshot.knowledgeBase().path("type").asText().equals("document")||!snapshot.knowledgeBase().path("auto_tag_config").path("enabled").asBoolean())return false;var payload=json.createObjectNode();for(String key:List.of("tenant_id","knowledge_id","knowledge_base_id"))payload.set(key,job.payload().path(key));for(String key:List.of("language","lf_trace_id","lf_parent_obs_id","lf_traceparent","lf_user_id","lf_session_id"))if(!job.payload().path(key).asText().isEmpty())payload.set(key,job.payload().get(key));if(job.payload().path("attempt").asLong()>0)payload.set("attempt",job.payload().get("attempt"));try{tasks.enqueue(job.tenantId(),type(),payload,new KnowledgeFileUpload.TaskOptions("summary",2,timeout()));return true;}catch(Exception e){return false;}}
  public JsonNode execute(TaskRecord job,TaskCancellation cancellation)throws Exception{
    var output=json.createObjectNode();var payload=job.payload();
    if(!payload.isNull()&&!payload.isObject())throw new TaskFailure("unmarshal automatic tag task payload",true);
    for(String key:List.of("tenant_id","attempt")){var value=payload.path(key);if(!value.isMissingNode()&&!value.isNull()&&(!value.isIntegralNumber()||!value.canConvertToLong()||(key.equals("tenant_id")&&value.asLong()<0)))throw new TaskFailure("unmarshal automatic tag task payload",true);}
    for(String key:List.of("knowledge_id","knowledge_base_id","language")){var value=payload.path(key);if(!value.isMissingNode()&&!value.isNull()&&!value.isTextual())throw new TaskFailure("unmarshal automatic tag task payload",true);}
    if(!payload.path("knowledge_id").asText().isEmpty()&&(job.tenantId()<=0||job.tenantId()!=payload.path("tenant_id").asLong()||payload.path("tenant_id").asLong()<=0||payload.path("knowledge_base_id").asText().isEmpty()))return output.put("skipped","knowledge_not_in_scope");
    var parent=tracker==null?null:tracker.lookupStage(job.tenantId(),payload.path("knowledge_id").asText(),payload.path("attempt").asLong(),"postprocess");var span=tracker==null?null:tracker.beginSubspan(parent,"postprocess.auto_tag","subspan",json.createObjectNode().put("knowledge_base_id",payload.path("knowledge_base_id").asText()));String code="AUTO_TAG_KNOWLEDGE_LOAD_FAILED";Exception failure=null;var watcher=Executors.newSingleThreadScheduledExecutor(r->{var t=new Thread(r,"native-auto-tag-cancellation");t.setDaemon(true);return t;});
    try(var call=CallContext.timeout(timeout())){var monitor=watcher.scheduleWithFixedDelay(()->{if(cancellation.isCanceled())call.cancel();},25,25,TimeUnit.MILLISECONDS);
      try{
        cancellation.check();if(repository.superseded(job))return output.put("skipped","attempt_superseded");var knowledge=repository.knowledge(job);if(knowledge==null||!knowledge.path("knowledge_base_id").equals(payload.path("knowledge_base_id")))return output.put("skipped","knowledge_not_in_scope");String state=knowledge.path("parse_status").asText();if(Set.of("cancelled","deleting","failed").contains(state))return output.put("skipped","knowledge_not_active").put("parse_status",state);
        code="AUTO_TAG_KB_LOAD_FAILED";var base=repository.base(job);if(base==null||!base.path("type").asText().equals("document"))return output.put("skipped","knowledge_base_not_eligible");var config=base.path("auto_tag_config");if(!config.path("enabled").asBoolean())return output.put("skipped","auto_tag_disabled");int maximum=KnowledgeAutoTagText.maximum(config);
        code="AUTO_TAG_LIST_TAGS_FAILED";var candidates=repository.candidates(job);var tags=candidates.tags();if(tags.isEmpty())return output.put("skipped","no_candidate_tags");boolean capped=candidates.total()>tags.size();code="AUTO_TAG_LOAD_EXISTING_FAILED";var existing=repository.existing(job);if(!existing.isEmpty()&&(!config.hasNonNull("skip_if_tagged")||config.path("skip_if_tagged").asBoolean()))return output.put("skipped","knowledge_already_tagged").put("existing_tag_count",existing.size());String model=SummaryGenerationText.trim(config.path("model_id").asText());if(model.isEmpty())model=SummaryGenerationText.trim(base.path("summary_model_id").asText());if(model.isEmpty())return output.put("skipped","model_not_configured");
        code="AUTO_TAG_LIST_CHUNKS_FAILED";var chunks=repository.chunks(job);if(!repository.bound(job,chunks))return output.put("skipped","chunk_binding_changed");String content=text.content(knowledge,chunks);if(SummaryGenerationText.trim(content).isEmpty())return output.put("skipped","no_text_chunks");code="AUTO_TAG_MODEL_LOAD_FAILED";var chat=models.chat(job.tenantId(),model);code="AUTO_TAG_MODEL_CALL_FAILED";var response=chat.chat(call,text.messages(tags,content,maximum),text.options());var matched=text.select(tags,response,maximum);
        cancellation.check();if(repository.superseded(job))return output.put("skipped","attempt_superseded");code="AUTO_TAG_KNOWLEDGE_LOAD_FAILED";var current=repository.knowledge(job);if(current==null||!current.path("knowledge_base_id").equals(payload.path("knowledge_base_id")))return output.put("skipped","knowledge_not_in_scope");if(!current.path("file_name").equals(knowledge.path("file_name")))return output.put("skipped","content_revision_changed");code="AUTO_TAG_LIST_CHUNKS_FAILED";if(!repository.current(job,chunks,repository.chunks(job)))return output.put("skipped","content_revision_changed");
        if(matched.isEmpty())return output.put("skipped","no_matching_tags").put("candidate_tag_count",tags.size()).put("candidate_tags_capped",capped).put("model_id",model);var added=matched.stream().filter(id->!existing.contains(id)).toList();if(added.isEmpty())return output.put("skipped","all_matches_already_attached").put("matched_tag_count",matched.size());code="AUTO_TAG_PERSIST_FAILED";repository.add(job,added);output.put("candidate_tag_count",tags.size()).put("candidate_tags_capped",capped).put("matched_tag_count",matched.size()).put("added_tag_count",added.size()).put("model_id",model);output.set("added_tag_ids",json.valueToTree(added));return output;
      }catch(Exception e){failure=e;throw e;}finally{monitor.cancel(false);if(tracker!=null){if(failure==null)tracker.end(span,output);else tracker.fail(span,code,Objects.requireNonNullElse(failure.getMessage(),"Automatic tagging failed"),failure);}}
    }finally{watcher.shutdownNow();}
  }
}
